#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include "systolic_stub.h"

/* generated by ICDeCompiler */
void matmul_i16(int16_t A[8][8], int16_t B[8][8], int32_t C[8][8]);

int main(void) {
    int16_t A[8][8], B[8][8];
    int32_t C[8][8];
    int32_t ref[8][8];

    /* fill with deterministic values */
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            A[i][j] = (int16_t)(i + j);
            B[i][j] = (int16_t)(i - j);
            C[i][j] = 0;
        }
    }

    /* reference: plain matmul */
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            int32_t acc = 0;
            for (int k = 0; k < 8; k++) {
                acc += (int32_t)A[i][k] * (int32_t)B[k][j];
            }
            ref[i][j] = acc;
        }
    }

    /* run the generated function */
    matmul_i16(A, B, C);

    /* compare */
    int mismatches = 0;
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            if (C[i][j] != ref[i][j]) {
                if (mismatches < 5) {
                    printf("mismatch at [%d][%d]: got %d, expected %d\n",
                           i, j, C[i][j], ref[i][j]);
                }
                mismatches++;
            }
        }
    }

    if (mismatches == 0) {
        printf("OK: generated code matches reference matmul\n");
        return 0;
    }
    printf("FAIL: %d mismatches\n", mismatches);
    return 1;
}